const nextCounterValue = `-- name: NextCounterValue :one

UPDATE document_counters SET next_value = next_value + 1, updated_at = now()
WHERE doc_type = $1 AND scope = '' RETURNING (next_value - 1)::bigint AS value
`

// Stage 21: stock counts.
// A gapless counter: the row lock serialises callers and a rolled-back count gives its number back (A-05).
func (q *Queries) NextCounterValue(ctx context.Context, docType string) (int64, error) {
	row := q.db.QueryRow(ctx, nextCounterValue, docType)
	var value int64
	err := row.Scan(&value)
	return value, err
}

const reversedReceiptItems = `-- name: ReversedReceiptItems :many
SELECT m.item_id FROM inventory_movements m
WHERE m.ref_type = 'purchase' AND m.ref_id = $1 AND m.movement_type = 'receipt'
  AND EXISTS (SELECT 1 FROM inventory_movements r WHERE r.reverses_movement_id = m.id)
`

// Receipts of a purchase that a reversal has since undone (the purchase itself stays received).
func (q *Queries) ReversedReceiptItems(ctx context.Context, refID pgtype.Int8) ([]int64, error) {
	rows, err := q.db.Query(ctx, reversedReceiptItems, refID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var item_id int64
		if err := rows.Scan(&item_id); err != nil {
			return nil, err
		}
		items = append(items, item_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

