const upsertCountLine = `-- name: UpsertCountLine :exec
INSERT INTO stock_count_lines (count_id, item_id, counted_base, entered_qty, entered_unit_id, expected_base)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (count_id, item_id) DO UPDATE SET counted_base = EXCLUDED.counted_base, entered_qty = EXCLUDED.entered_qty, entered_unit_id = EXCLUDED.entered_unit_id,
  expected_base = EXCLUDED.expected_base, saved_at = now()
`

type UpsertCountLineParams struct {
	CountID       int64
	ItemID        int64
	CountedBase   int64
	EnteredQty    int64
	EnteredUnitID int64
	ExpectedBase  int64
}

func (q *Queries) UpsertCountLine(ctx context.Context, arg UpsertCountLineParams) error {
	_, err := q.db.Exec(ctx, upsertCountLine,
		arg.CountID,
		arg.ItemID,
		arg.CountedBase,
		arg.EnteredQty,
		arg.EnteredUnitID,
		arg.ExpectedBase,
	)
	return err
}
